#define WN 4        // accumulator tiles, N direction; MODE 1 needs a multiple of 4
#endif
#ifndef BK_TILES
#define BK_TILES 2  // K-slab depth, in 16-wide cooperative-matrix steps
#endif
// The stream count is compiled in rather than read from pc.hc: MODE 1's
// collapse is a reduction over it *and* the weight permutation that puts the
// streams of one feature in one workgroup is cut on it, so a mismatch would
// be a wrong answer and not a slow one. The host checks the checkpoint says 4.
#ifndef HC_STREAMS
#define HC_STREAMS 4
#endif

#define TILE 16
#define BM (WM * TILE)
#define BN (WN * TILE)
#define BK (BK_TILES * TILE)
#define WAVE 64

layout(local_size_x = WAVE) in;

#ifdef QBANK
// §2.2's pad, and L5b's reason for its size: a slab row of BK + 8 halves
// keeps every row sixteen-byte aligned, which is what the cooperative-matrix
// load off LDS needs to take its wide path, and eight of the 32 banks is as
// good as a four-dword-aligned stride gets.
#define LDS_PAD 8
#define LDS_ROW (BK + LDS_PAD)
shared float16_t sQB[BN * LDS_ROW];
#endif

#ifdef Q4B
#include "llm_q4k.glsl"
// A k-slab is exactly one 32-element group, which is what lets the record be
// decoded once a slab into BN floats rather than once per unpacked word. It
// is a compile-time fact of every build in shaders.go and the arithmetic
// below assumes it rather than testing it.
#if BK != 32
#error "the q4_k arm wants BK_TILES = 2, so that a k-slab is one scale group"
#endif
// **How many groups share one fp16 pair**, and the one thing about this bank
// that is not the same in every build: LLM.md L8c-6. Eight is ggml's QK_K/32
// and every matrix in this model whose k is a multiple of 256; ten is the
// 320-wide hyper-connection up projection, whose super-block is the whole row
// because `get_scale_min_k4` is four low pairs and four high ones and not a
// length. The two differ in three numbers — the super-block's extent, the
// record's word count and which decode reads it — and in nothing else.
#ifndef Q4K_SUB
#define Q4K_SUB 8
#endif
#define Q4K_SB (32u * uint(Q4K_SUB))
#if Q4K_SUB == 8
#define Q4K_REC_WORDS 4u
#else
#define Q4K_REC_WORDS 5u
#endif
shared float sQS[BN];   // d * sc for this slab's group, per column
shared float sQM[BN];   // dmin * m, the same
#endif

#define FRAG_A_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseA>
#define FRAG_B_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseB>
#define ACC_T coopmat<float, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>
#define ACC16_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>

#if MODE == 1
#define A_BUF_OFF pc.loOff
