package llm

// P1a's gate: the fused combine+norm is the pair, to the last place.
//
//	go test ./llm/ -v -run TestHCFusionIsTheCombineThenTheNorm   # 4 layers, ~4 s
//
// The fusion is a *scheduling* change and not an arithmetic one, and this is
// what says so. `llm_hc_cn.comp` runs one mixer's scatter and the next
// mixer's grouped RMSNorm in a single workgroup per (token, stream), keeping
// the combined residual in registers instead of going back to the arena — but
// it keeps the norm's 256-thread partition and its 256-way tree, because a
// wider workgroup would be a different sum over 2560 squares. So the two arms
// have to agree **bit for bit**, on both tensors the boundary produces: the
// wide residual every combine updates, and `mixed`, which is the norm's whole
// downstream.
//
// A tolerance would not do here. The pair and the fusion read the same
// weights in the same order; if they disagree at all it is because a value
// took a different path, and 1e-7 of that is as much a defect as 1e-2.

import (
	"testing"
)

func TestHCFusionIsTheCombineThenTheNorm(t *testing.T) {
	const layers = 4
	g, _, ids := graphFixture(t, GraphOpts{Layers: layers, NoHead: true})

	run := func(fuse bool) ([]float32, []float32) {
		t.Helper()
		t.Setenv("LLM_HC_NOFUSE", map[bool]string{true: "0", false: "1"}[fuse])
		if err := g.PrefillN(ids, layers); err != nil {
			t.Fatal(err)
		}
		res := append([]float32(nil), g.Residual()...)
		mixed := append([]float32(nil), g.hc.Mixed()...)
		return res, mixed
	}

	fusedRes, fusedMixed := run(true)
	pairRes, pairMixed := run(false)

	for _, c := range []struct {
		name       string
		got, want  []float32
	}{
		{"l_last-3", fusedRes, pairRes},
		{"mixed", fusedMixed, pairMixed},
	} {
